import React from 'react'
import { Link, useTranslations } from 'demo'

export function generateMetadata({ locale }: { locale: string }) {
  if (locale === "zh") {
    return { title: "关于我们", description: "了解我们" }
  }

  return { title: "About Us", description: "Learn about us" }
}

const FAQS_ZH = [
  { q: "问题一", a: "答案一" },
  { q: "问题二", a: "答案二" },
]

export default function About() {
  const t = useTranslations()
  return (
    <div className="hero-art" aria-label="关系地图">
      <small>今日会员消费</small>
      <strong>¥ 8,420</strong>
      <a href="/news">新闻</a>
    </div>
  )
}

